svg.script:
/*  */
(function() {
  var root = document.getElementById('fm1p6-svg');
  if (!root) return;

  var btnStimulate = root.getElementById('fm1p6-btn-stimulate');
  var btnNormal = root.getElementById('fm1p6-btn-normal');
  var btnBabinski = root.getElementById('fm1p6-btn-babinski');

  var stageNormal = root.getElementById('fm1p6-stage-normal');
  var stageBabinski = root.getElementById('fm1p6-stage-babinski');

  var noteNormal = root.getElementById('fm1p6-dynamic-note-normal');
  var noteBabinski = root.getElementById('fm1p6-dynamic-note-babinski');

  var normalHallux = root.getElementById('fm1p6-normal-hallux');
  var pathoHallux = root.getElementById('fm1p6-patho-hallux');

  function setMode(mode) {
    if (mode === 'normal') {
      btnNormal.classList.add('fm1p6-active-normal');
      btnBabinski.classList.remove('fm1p6-active-babinski');

      stageNormal.setAttribute('opacity', '1');
      stageBabinski.setAttribute('opacity', '0.45');

      noteNormal.setAttribute('opacity', '1');
      noteBabinski.setAttribute('opacity', '0.2');
    } else if (mode === 'babinski') {
      btnNormal.classList.remove('fm1p6-active-normal');
      btnBabinski.classList.add('fm1p6-active-babinski');

      stageNormal.setAttribute('opacity', '0.45');
      stageBabinski.setAttribute('opacity', '1');

      noteNormal.setAttribute('opacity', '0.2');
      noteBabinski.setAttribute('opacity', '1');
    } else {
      // Compare Both
      btnNormal.classList.remove('fm1p6-active-normal');
      btnBabinski.classList.remove('fm1p6-active-babinski');

      stageNormal.setAttribute('opacity', '1');
      stageBabinski.setAttribute('opacity', '1');

      noteNormal.setAttribute('opacity', '1');
      noteBabinski.setAttribute('opacity', '1');
    }
  }

  function runStimulusAnimation() {
    stageNormal.classList.remove('fm1p6-active-sweep');
    stageBabinski.classList.remove('fm1p6-active-sweep');

    // Force reflow
    void stageNormal.offsetWidth;

    stageNormal.classList.add('fm1p6-active-sweep');
    stageBabinski.classList.add('fm1p6-active-sweep');

    // Animate heads along path manually for maximum compatibility
    var headLeft = root.getElementById('fm1p6-head-left');
    var headRight = root.getElementById('fm1p6-head-right');

    var startTime = null;
    var duration = 1200; // ms

    // Waypoints matching path "M 100 270 C 185 240, 195 150, 150 105 L 100 95"
    function animateHead(timestamp) {
      if (!startTime) startTime = timestamp;
      var progress = (timestamp - startTime) / duration;
      if (progress > 1) progress = 1;

      // Simple parametric approximation for stimulus sweep
      var t = progress;
      var cx, cy;
      if (t < 0.8) {
        var nt = t / 0.8;
        cx = 100 + 95 * Math.sin(nt * Math.PI);
        cy = 270 - 165 * nt;
      } else {
        var nt2 = (t - 0.8) / 0.2;
        cx = 150 - 50 * nt2;
        cy = 105 - 10 * nt2;
      }

      if (headLeft) { headLeft.setAttribute('cx', cx); headLeft.setAttribute('cy', cy); }
      if (headRight) { headRight.setAttribute('cx', cx); headRight.setAttribute('cy', cy); }

      if (progress < 1) {
        requestAnimationFrame(animateHead);
      } else {
        setTimeout(function() {
          if (headLeft) { headLeft.setAttribute('cx', 100); headLeft.setAttribute('cy', 270); }
          if (headRight) { headRight.setAttribute('cx', 100); headRight.setAttribute('cy', 270); }
        }, 800);
      }
    }

    requestAnimationFrame(animateHead);
  }

  // Event Listeners
  if (btnNormal) {
    btnNormal.addEventListener('click', function() { setMode('normal'); });
    btnNormal.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setMode('normal'); e.preventDefault(); } });
  }

  if (btnBabinski) {
    btnBabinski.addEventListener('click', function() { setMode('babinski'); });
    btnBabinski.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { setMode('babinski'); e.preventDefault(); } });
  }

  if (btnStimulate) {
    btnStimulate.addEventListener('click', runStimulusAnimation);
    btnStimulate.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { runStimulusAnimation(); e.preventDefault(); } });
  }

  if (normalHallux) {
    normalHallux.addEventListener('click', function() { setMode('normal'); });
  }
  if (pathoHallux) {
    pathoHallux.addEventListener('click', function() { setMode('babinski'); });
  }

  // Initial state: side by side active comparison
  setMode('both');
})();
/*  */
